/* ============================================
   ARTIFACT CARD COMPONENT
   An artifact's place in a conversation: a mark, the name over its kind,
   and a cue for what a press does. One row, the width of a card, and a
   toggle button: pressed while its artifact is on stage in the panel.
   ============================================ */

/* Base */

.ds-artifact-card {
  box-sizing: border-box;
  display: flex;
  align-items: center;
  gap: var(--gap-300);
  /* The column's full width, like every chat card. */
  width: 100%;
  padding: var(--padding-300);
  border: var(--ds-chat-card-border);
  border-radius: var(--ds-chat-card-radius);
  background-color: var(--ds-chat-card-bg);
  cursor: pointer;
  text-align: start;
  transition:
    background-color var(--motion-duration-fast) var(--motion-ease-standard),
    border-color var(--motion-duration-fast) var(--motion-ease-standard);
}

.ds-artifact-card:hover {
  background-color: var(--color-action-passive-bg-hover);
}

.ds-artifact-card:focus-visible {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* States */

/* On stage, the tile holds the "on stage" fill ThreadPanel's active row and
   ThreadTabs' active tab wear. */
.ds-artifact-card--open {
  background-color: var(--color-bg-container-tertiary);
}

/* The mark steps to the card's resting fill while the card holds the
   on-stage one, so it stays a tile on the card instead of dissolving into
   a fill of nearly its own value. */
.ds-artifact-card--open .ds-artifact-card__mark {
  background-color: var(--ds-chat-card-bg);
}

.ds-artifact-card__mark {
  --icon-size: var(--icon-size-600);
  display: flex;
  flex: none;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  /* Concentric with the card: its radius less the padding between them,
     computed from the live tokens so the corner holds under any theme's
     radius scale, and squares off with a squared theme. */
  border-radius: max(0px, calc(var(--ds-chat-card-radius) - var(--padding-300)));
  background-color: var(--color-bg-container-secondary);
  color: var(--color-icon-primary);
}

.ds-artifact-card__text {
  display: flex;
  flex: 1;
  flex-direction: column;
  min-width: 0;
}

.ds-artifact-card__title {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-title-body-family);
  font-size: var(--font-title-body-size);
  font-weight: var(--font-title-body-weight);
  line-height: var(--font-title-body-line-height);
  letter-spacing: var(--font-title-body-letter-spacing);
  color: var(--color-text-primary);
}

.ds-artifact-card__meta {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-family: var(--font-caption-family);
  font-size: var(--font-caption-size);
  font-weight: var(--font-caption-weight);
  line-height: var(--font-caption-line-height);
  color: var(--color-text-tertiary);
}

.ds-artifact-card__cue {
  --icon-size: var(--icon-size-500);
  flex: none;
  color: var(--color-icon-secondary);
}

.ds-artifact-card:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

import React from 'react';
import './ArtifactCard.css';
import '../../behaviors/chat-card.css';
import '../../fonts/material-symbols.css';
import { mirrorClass } from '../../behaviors/direction';

/** Props owned by ArtifactCard itself — everything else falls through to the root `<button>`. */
type ArtifactCardOwnProps = {
  /** The artifact's name. Collides with the native `title` tooltip attribute on purpose: the card shows its name, it does not hide it in a tooltip. */
  title: React.ReactNode;
  /** A quiet line under the name: what kind of thing this is, or which version. */
  meta?: React.ReactNode;
  /** The leading mark — Material Symbol name (string) or custom element (ReactNode). */
  icon?: string | React.ReactNode;
  /** Whether this card's artifact is on stage in its panel. The card holds the on-stage fill, announces itself pressed, and its trailing cue turns from open to close. */
  open?: boolean;
  /** Additional CSS classes */
  className?: string;
};

export interface ArtifactCardProps
  extends ArtifactCardOwnProps,
    Omit<React.ComponentPropsWithoutRef<'button'>, keyof ArtifactCardOwnProps | 'type'> {}

const baseClass = 'ds-artifact-card';

/** The trailing cue: the panel's open or close mark. */
const cueIcon = (open: boolean) => (open ? 'right_panel_close' : 'right_panel_open');

/**
 * ArtifactCard is an artifact's place in a conversation: one row naming
 * something the chat made, which opens it in an ArtifactPanel. It is a
 * toggle button, so `open` is the whole state and `onClick` the whole
 * behaviour; the host decides what opening means.
 *
 * Hook-free and stateless, so it renders from a Server Component until it
 * is given a handler.
 */
export const ArtifactCard = React.forwardRef<HTMLButtonElement, ArtifactCardProps>(
  ({ title, meta, icon = 'draft', open = false, className = '', ...rest }, ref) => (
    <button
      ref={ref}
      {...rest}
      type="button"
      className={[baseClass, open && `${baseClass}--open`, className].filter(Boolean).join(' ')}
      aria-pressed={open}
    >
      {typeof icon === 'string' ? (
        <span className={`${baseClass}__mark material-symbols-rounded ${mirrorClass(icon)}`} aria-hidden="true">
          {icon}
        </span>
      ) : (
        <span className={`${baseClass}__mark`}>{icon}</span>
      )}
      <span className={`${baseClass}__text`}>
        <span className={`${baseClass}__title`}>{title}</span>
        {meta && <span className={`${baseClass}__meta`}>{meta}</span>}
      </span>
      {/* The chat widget's artifact toggle's glyphs, so the card and the
          header control that open the same panel draw the same mark. */}
      <span className={`${baseClass}__cue material-symbols-rounded ${mirrorClass(cueIcon(open))}`} aria-hidden="true">
        {cueIcon(open)}
      </span>
    </button>
  )
);

ArtifactCard.displayName = 'ArtifactCard';
